+class ContactForm {
+    constructor(formId) {
+        this.form = document.getElementById(formId);
+        this.fullNameInput = document.getElementById('fullName');
+        this.emailInput = document.getElementById('email');
+        this.phoneInput = document.getElementById('phone');
+        this.fullNameError = document.getElementById('fullNameError');
+        this.emailError = document.getElementById('emailError');
+        this.phoneError = document.getElementById('phoneError');
+        this.successMessage = document.getElementById('successMessage');
+
+        this.init();
+    }
+
+    init() {
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        this.fullNameInput.addEventListener('blur', () => this.validateFullName());
+        this.fullNameInput.addEventListener('input', () => this.validateFullName());
+        this.emailInput.addEventListener('blur', () => this.validateEmail());
+        this.emailInput.addEventListener('input', () => this.validateEmail());
+        this.phoneInput.addEventListener('blur', () => this.validatePhone());
+        this.phoneInput.addEventListener('input', () => this.validatePhone());
+    }
+
+    validateFullName() {
+        const value = this.fullNameInput.value.trim();
+
+        if (!value) {
+            this.setError(this.fullNameInput, this.fullNameError, 'Full name is required');
+            return false;
+        }
+
+        if (value.length < 2) {
+            this.setError(this.fullNameInput, this.fullNameError, 'Full name must be at least 2 characters');
+            return false;
+        }
+
+        this.clearError(this.fullNameInput, this.fullNameError);
+        return true;
+    }
+
+    validateEmail() {
+        const value = this.emailInput.value.trim();
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+        if (!value) {
+            this.setError(this.emailInput, this.emailError, 'Email address is required');
+            return false;
+        }
+
+        if (!emailRegex.test(value)) {
+            this.setError(this.emailInput, this.emailError, 'Please enter a valid email address');
+            return false;
+        }
+
+        this.clearError(this.emailInput, this.emailError);
+        return true;
+    }
+
+    validatePhone() {
+        const value = this.phoneInput.value.trim();
+
+        if (!value) {
+            this.clearError(this.phoneInput, this.phoneError);
+            return true;
+        }
+
+        const phoneRegex = /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/;
+
+        if (!phoneRegex.test(value)) {
+            this.setError(this.phoneInput, this.phoneError, 'Please enter a valid phone number');
+            return false;
+        }
+
+        this.clearError(this.phoneInput, this.phoneError);
+        return true;
+    }
+
+    setError(input, errorElement, message) {
+        input.classList.add('error');
+        input.classList.remove('success');
+        errorElement.textContent = message;
+        errorElement.classList.add('show');
+    }
+
+    clearError(input, errorElement) {
+        input.classList.remove('error');
+        input.classList.add('success');
+        errorElement.textContent = '';
+        errorElement.classList.remove('show');
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+
+        const isFullNameValid = this.validateFullName();
+        const isEmailValid = this.validateEmail();
+        const isPhoneValid = this.validatePhone();
+
+        if (isFullNameValid && isEmailValid && isPhoneValid) {
+            this.showSuccessMessage();
+            this.resetForm();
+        }
+    }
+
+    showSuccessMessage() {
+        this.successMessage.textContent = 'Thank you! Your message has been sent successfully.';
+        this.successMessage.classList.add('show');
+
+        setTimeout(() => {
+            this.successMessage.classList.remove('show');
+        }, 5000);
+    }
+
+    resetForm() {
+        this.form.reset();
+        this.fullNameInput.classList.remove('success', 'error');
+        this.emailInput.classList.remove('success', 'error');
+        this.phoneInput.classList.remove('success', 'error');
+        this.fullNameError.classList.remove('show');
+        this.emailError.classList.remove('show');
+        this.phoneError.classList.remove('show');
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactForm('contactForm');
+});
+
")

